var ranges = (process.env["RANGES"] ?? "600,800,1000,1200,1500,2000").split(",").map(Number);
var rng = new SeededRng(1);
var REPS = env("REPS", 10);
console.log(`# fan-sim ${id}\uFF08${rec["length_m"]} \xD7 ${rec["beam_m"]} m\u30FB\u5186 ${CIRC}\u30FB${env("KT", us05.v0_1_prototype.transit.speed_kt)} kt\u30FB\u65CB\u56DE ${ai.turnRateDegS}\xB0/\u79D2\u30FB\u56DE\u907F\u306E\u8EE2\u8235 ${ai.evadeTurnRateDegS}\xB0/\u79D2\u30FB\u53CD\u5FDC ${ai.reactionDelayS} \u79D2\uFF09: ${N} \u672C\u306E\u6247\u30FB\u9593\u9694 ${SP}\xB0\u30FB${INT} \u79D2\u304A\u304D${mag ? `\u30FB\u5F3E\u85AC\u5EAB ${mag.on_hits.join("\u30FB")} \u672C\u76EE ${mag.chance.map((c) => `${c * 100}%`).join("\u30FB")}` : ""}`);
for (const r of ranges) {
  const dist = new Array(N + 1).fill(0);
  let n = 0, mg = 0;
  for (let bg = 0; bg <= 180; bg += 15) for (const e of [-3, -1.5, 0, 1.5, 3]) for (let q = 0; q < REPS; q++) {
    const h = fan(r, bg, e, rng);
    if (h < 0) break;
    dist[h]++;
    n++;
    mg += magazineExpect(h);
  }
  const pc = (c) => (100 * c / n).toFixed(1);
  const mean = dist.reduce((a, c, i) => a + c * i, 0) / n, ge3 = dist.slice(3).reduce((a, c) => a + c, 0);
  console.log(`${String(r).padStart(5)} m  n=${n}  0..${N} \u672C: ${dist.map(pc).join(" / ")} %  \u5E73\u5747 ${mean.toFixed(2)}  1 \u672C\u4EE5\u4E0A ${pc(n - dist[0])}%  3 \u672C\u4EE5\u4E0A ${pc(ge3)}%  ${N} \u672C ${pc(dist[N])}%${mag ? `  \u5F3E\u85AC\u5EAB\u306E\u671F\u5F85\u5024 ${(1e3 * mg / n).toFixed(1)}\uFF0F1,000 \u56DE` : ""}`);
}
